let pictureRequestView=null;
const pictureKey=row=>JSON.stringify([row.kind,row.id]);
function pictureRequestCard(){return `<section class="panel mt catalogue-pictures-intro"><div class="row">${uiTile('photos','blue')}<div><h2>Illustrated Catalogue · picture research</h2><p class="muted">Already added your products? Ask your own AI to find pictures for existing parts and workshop supplies.</p></div></div><div class="actions mt">${btn('Create picture request','pictures-open')}${btn('Saved picture requests','pictures-saved')}${btn('Open completed picture files…','illustrated-import','primary')}</div><p class="tiny muted">Exports only product descriptions and references, in files of up to 100 entries. Select one or several completed JSON files to review them together. Previews download automatically after validation; queued downloads continue when imports free temporary space. Select pictures, then use Finish import at the bottom right.</p></section>`;}
function pictureBody(){const v=pictureRequestView,r=v.result,f=v.filters,option=(value,label,current)=>`<option value="${esc(value)}" ${value===current?'selected':''}>${esc(label)}</option>`;
 return `<p>Choose a manufacturer, filter its products and select the entries to research. Owned and zero-stock entries are included. Selections stay checked across pages and filters.</p>${!r.manufacturers.length?'<p class="note info">Add a manufacturer to your parts or workshop supplies first.</p>':''}<div class="form-grid"><label class="field">Manufacturer<select id="pictures-maker">${option('','Choose a manufacturer',f.manufacturer)}${r.manufacturers.map(m=>option(m,m,f.manufacturer)).join('')}</select></label><label class="field">Items<select id="pictures-kind">${option('','Parts and workshop supplies',f.kind)}${option('part','Parts',f.kind)}${option('supply','Workshop supplies',f.kind)}</select></label><label class="field">Category<select id="pictures-category">${option('','All categories',f.category)}${r.categories.map(c=>option(c,c,f.category)).join('')}</select></label><label class="field">Search<input id="pictures-query" value="${esc(f.query)}" maxlength="500" placeholder="Name, reference or type"></label></div><label class="check-row"><input type="checkbox" id="pictures-missing" ${f.missing?'checked':''}>Only entries without pictures</label><div class="actions mt">${btn('Apply filters','pictures-filter')}${btn('Select all filtered','pictures-select')}${btn('Clear selection','pictures-clear')}</div><p class="tiny muted">A product reference helps identify the exact variant. Entries without one are marked below. This researches product pictures, not the condition of your own item. Existing pictures are not replaced by exporting.</p><p id="pictures-count" aria-live="polite">${v.selected.size} selected · ${Math.ceil(v.selected.size/100)} request file(s)</p><div class="table-wrap picture-request-table"><table><thead><tr><th>Select</th><th>Product</th><th>Reference</th><th>Picture</th></tr></thead><tbody>${f.manufacturer?r.rows.map(row=>`<tr><td><input type="checkbox" aria-label="Select ${esc(row.name)}" data-picture-row="${esc(pictureKey(row))}" ${v.selected.has(pictureKey(row))?'checked':''}></td><td><strong>${esc(row.name)}</strong><br><small>${esc([row.kind==='part'?'Part':'Workshop supply',row.category,row.partType].filter(Boolean).join(' · '))}</small></td><td>${row.reference.trim()?esc(row.reference):badge('No reference','warn')}</td><td>${row.hasPicture?'Existing picture':'Missing'}</td></tr>`).join('')||'<tr><td colspan="4">No matching entries.</td></tr>':'<tr><td colspan="4">Choose a manufacturer to see its entries.</td></tr>'}</tbody></table></div><div class="actions mt">${f.manufacturer&&r.offset?btn('Previous','pictures-prev'):''}${f.manufacturer&&r.next!==null?btn('Next','pictures-next'):''}<span>${f.manufacturer?r.total:0} matching entries</span></div><p class="tiny muted">No quantities, locations, prices, personal notes or photo data are exported. Saved request mappings stay on this computer and are not included in library backups.</p><p id="pictures-export-result" role="status"></p>`;
}
function pictureCount(){const el=$('#pictures-count');if(el&&pictureRequestView)el.textContent=pictureRequestView.selected.size+' selected · '+Math.ceil(pictureRequestView.selected.size/100)+' request file(s)';}
async function pictureLoad(offset=0){const v=pictureRequestView,result=await api('file','pictures.browse',{filters:v.filters,offset,expected:v.result});if(pictureRequestView!==v||!$('#picture-content'))return;v.result=result;$('#picture-content').innerHTML=pictureBody();}
async function pictureSaved(){const expected=await api('file','pictures.browse',{}),result=await api('file','pictures.requests',{expected});pictureRequestView={result,selected:new Map()};modal('Saved picture requests',`<p>Requests and downloaded previews are saved on this computer. Re-export keeps the same row identities. Discard only requests you no longer need; their returned files will no longer be usable.</p><p class="note info">Preview selections do not change your catalogue. Open the previews, choose pictures and use Finish import at the bottom right. Successful imports close automatically; Dealership submissions are sent for review.</p>${result.requests.map(r=>`<section class="panel mt"><strong>${esc(r.manufacturer)}</strong><p>${r.count} entries · ${esc(r.created)}${r.databaseId!==result.databaseId?' · Another collection':r.recoveryId!==result.recoveryId?' · Old recovery generation':''}</p><p class="tiny muted">${esc(r.id)}</p><div class="actions">${r.databaseId===result.databaseId&&r.recoveryId===result.recoveryId?btn('Export again…','pictures-again','',r.id)+(r.state==='preview'?btn('Open previews','illustrated-open','primary',r.id):''):''}${btn('Discard request','pictures-discard','danger',r.id)}</div></section>`).join('')||'<p>No saved picture requests on this computer.</p>'}`,null);}
async function pictureAction(action,id){
 if(!action.startsWith('pictures-'))return false;if(!local())return true;
 if(action==='pictures-open'){const result=await api('file','pictures.browse',{});pictureRequestView={result,filters:{manufacturer:'',kind:'',category:'',query:'',missing:true},selected:new Map()};modal('Illustrated Catalogue · create picture request','<div id="picture-content"></div>',null);$('#picture-content').innerHTML=pictureBody();$('#dialog .dialog-footer').insertAdjacentHTML('beforeend',btn('Export picture requests…','pictures-export','primary'));return true;}
 if(action==='pictures-saved'){await pictureSaved();return true;}
 const v=pictureRequestView;if(!v)return true;
 if(action==='pictures-filter'){const manufacturer=$('#pictures-maker').value,missing=$('#pictures-missing').checked;if(manufacturer!==v.filters.manufacturer||missing!==v.filters.missing)v.selected.clear();v.filters={manufacturer,missing,kind:$('#pictures-kind').value,category:manufacturer!==v.filters.manufacturer?'':$('#pictures-category').value,query:$('#pictures-query').value};await pictureLoad();}
 if(action==='pictures-select'){const rows=await api('file','pictures.select',{filters:v.filters,expected:v.result});for(const row of rows)v.selected.set(pictureKey(row),row);if($('#picture-content'))$('#picture-content').innerHTML=pictureBody();}
 if(action==='pictures-clear'){v.selected.clear();$('#picture-content').innerHTML=pictureBody();}
 if(action==='pictures-next')await pictureLoad(v.result.next);
 if(action==='pictures-prev')await pictureLoad(Math.max(0,v.result.offset-40));
 if(action==='pictures-export'){const result=await api('file','pictures.export',{expected:v.result,manufacturer:v.filters.manufacturer,selected:[...v.selected.values()],includeExisting:!v.filters.missing});if(result){v.selected.clear();document.querySelectorAll('[data-picture-row]').forEach(el=>el.checked=false);pictureCount();const output=$('#pictures-export-result');if(output)output.textContent=`Saved ${result.items} entries in ${result.files} request file(s) to ${result.path}. Give each JSON file to your AI; English instructions are included.`;toast('Picture requests saved.');}}
 if(action==='pictures-again'){const result=await api('file','pictures.reexport',{id,expected:v.result});if(result)toast('Picture request saved to '+result.path);}
 if(action==='pictures-discard')modal('Discard picture request?','<p>The returned AI file for this request will no longer be usable. No products or photographs will change.</p>',async()=>{await api('file','pictures.discard',{id,expected:v.result,requestDatabaseId:v.result.requests.find(r=>r.id===id)?.databaseId});toast('Request discarded.');},'Discard request');
 return true;
}
document.addEventListener('change',event=>{const key=event.target.dataset?.pictureRow,v=pictureRequestView;if(!key||!v)return;const row=v.result.rows.find(r=>pictureKey(r)===key);if(!row)return;if(event.target.checked)v.selected.set(key,{kind:row.kind,id:row.id});else v.selected.delete(key);pictureCount();});
